/* Supabase Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="supabase-light"] {
  --background: rgb(252, 252, 252);
  --foreground: rgb(22, 22, 22);
  --card: rgb(252, 252, 252);
  --card-foreground: rgb(22, 22, 22);
  --popover: rgb(252, 252, 252);
  --popover-foreground: rgb(82, 82, 82);
  --primary: rgb(113, 225, 172);
  --primary-foreground: rgb(32, 38, 35);
  --secondary: rgb(252, 252, 252);
  --secondary-foreground: rgb(22, 22, 22);
  --muted: rgb(238, 238, 238);
  --muted-foreground: rgb(31, 31, 31);
  --accent: rgb(238, 238, 238);
  --accent-foreground: rgb(31, 31, 31);
  --destructive: rgb(200, 51, 22);
  --destructive-foreground: rgb(252, 252, 252);
  --border: rgb(222, 222, 222);
  --input: rgb(245, 245, 245);
  --ring: rgb(113, 225, 172);
  --chart-1: rgb(113, 225, 172);
  --chart-2: rgb(57, 129, 246);
  --chart-3: rgb(140, 93, 248);
  --chart-4: rgb(244, 159, 30);
  --chart-5: rgb(16, 186, 130);
  --radius: 0.5rem;
  --sidebar: rgb(252, 252, 252);
  --sidebar-foreground: rgb(113, 113, 113);
  --sidebar-primary: rgb(113, 225, 172);
  --sidebar-primary-foreground: rgb(32, 38, 35);
  --sidebar-accent: rgb(238, 238, 238);
  --sidebar-accent-foreground: rgb(31, 31, 31);
  --sidebar-border: rgb(222, 222, 222);
  --sidebar-ring: rgb(113, 225, 172);
  --font-sans: Outfit, sans-serif;
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.17;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 1px;
  --letter-spacing: 0.025em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 1px 3px 0px hsl(0 0% 0% / 0.09);
  --shadow-xs: 0px 1px 3px 0px hsl(0 0% 0% / 0.09);
  --shadow-sm:
    0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 1px 2px -1px hsl(0 0% 0% / 0.17);
  --shadow:
    0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 1px 2px -1px hsl(0 0% 0% / 0.17);
  --shadow-md:
    0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 2px 4px -1px hsl(0 0% 0% / 0.17);
  --shadow-lg:
    0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 4px 6px -1px hsl(0 0% 0% / 0.17);
  --shadow-xl:
    0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 8px 10px -1px hsl(0 0% 0% / 0.17);
  --shadow-2xl: 0px 1px 3px 0px hsl(0 0% 0% / 0.43);
  --tracking-normal: 0.025em;
}

