  --popover-foreground: rgb(168, 168, 168);
  --primary: rgb(13, 98, 59);
  --primary-foreground: rgb(223, 231, 227);
  --secondary: rgb(36, 36, 36);
  --secondary-foreground: rgb(252, 252, 252);
  --muted: rgb(31, 31, 31);
  --muted-foreground: rgb(161, 161, 161);
  --accent: rgb(48, 48, 48);
  --accent-foreground: rgb(252, 252, 252);
  --destructive: rgb(85, 25, 18);
  --destructive-foreground: rgb(235, 235, 235);
  --border: rgb(41, 41, 41);
  --input: rgb(36, 36, 36);
  --ring: rgb(76, 222, 129);
  --chart-1: rgb(76, 222, 129);
  --chart-2: rgb(97, 164, 247);
  --chart-3: rgb(167, 139, 251);
  --chart-4: rgb(251, 192, 49);
  --chart-5: rgb(50, 210, 189);
  --radius: 0.5rem;
  --sidebar: rgb(18, 18, 18);
  --sidebar-foreground: rgb(137, 137, 137);
  --sidebar-primary: rgb(13, 98, 59);
  --sidebar-primary-foreground: rgb(223, 231, 227);
  --sidebar-accent: rgb(48, 48, 48);
  --sidebar-accent-foreground: rgb(252, 252, 252);
  --sidebar-border: rgb(41, 41, 41);
  --sidebar-ring: rgb(76, 222, 129);
  --font-sans: Outfit, sans-serif;
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.17;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 1px;
  --letter-spacing: 0.025em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 1px 3px 0px hsl(0 0% 0% / 0.09);
  --shadow-xs: 0px 1px 3px 0px hsl(0 0% 0% / 0.09);
  --shadow-sm:
    0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 1px 2px -1px hsl(0 0% 0% / 0.17);
  --shadow:
    0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 1px 2px -1px hsl(0 0% 0% / 0.17);
  --shadow-md:
    0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 2px 4px -1px hsl(0 0% 0% / 0.17);
  --shadow-lg:
    0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 4px 6px -1px hsl(0 0% 0% / 0.17);
  --shadow-xl:
    0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 8px 10px -1px hsl(0 0% 0% / 0.17);
  --shadow-2xl: 0px 1px 3px 0px hsl(0 0% 0% / 0.43);
}
